jsonSpec.spec:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "width": "container",
  "height": "container",
  "data": {
    "name": "databricks_query"
  },
  "config": {
    "autosize": {
      "type": "fit",
      "contains": "padding"
    },
    "background": "#1a1a2e",
    "view": {
      "stroke": null
    },
    "axis": {
      "labelColor": "#e0e0e0",
      "titleColor": "#e0e0e0",
      "gridColor": "#333355"
    },
    "legend": {
      "labelColor": "#e0e0e0",
      "titleColor": "#e0e0e0"
    }
  },
  "title": {
    "text": "Today vs Normal — Incident Severity",
    "subtitle": "Red = crisis now | Blue = 90-day baseline",
    "color": "#ff6b6b"
  },
  "transform": [
    {
      "fold": [
        "cancel_pct",
        "disrupted_pct",
        "avg_late_min"
      ],
      "as": [
        "metric",
        "value"
      ]
    },
    {
      "calculate": "datum.metric === 'cancel_pct' ? 'Cancellation %' : datum.metric === 'disrupted_pct' ? 'Disruption %' : 'Avg Late (min)'",
      "as": "metric_label"
    },
    {
      "calculate": "datum.value === null ? 0 : datum.value",
      "as": "value"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "line",
        "interpolate": "linear-closed",
        "strokeWidth": 3,
        "point": {
          "filled": true,
          "size": 80
        }
      },
      "encoding": {
        "x": {
          "field": "metric_label",
          "type": "nominal",
          "title": null,
          "axis": {
            "labelAngle": 0,
            "labelColor": "#e0e0e0"
          }
        },
        "y": {
          "field": "value",
          "type": "quantitative",
          "title": "Value",
          "axis": {
            "labelColor": "#e0e0e0",
            "gridColor": "#333355"
          }
        },
        "color": {
          "field": "period",
          "type": "nominal",
          "scale": {
            "domain": [
              "today (this run)",
              "normal (90-day avg)"
            ],
            "range": [
              "#ff4444",
              "#4488ff"
            ]
          },
          "title": "Period"
        },
        "strokeDash": {
          "field": "period",
          "type": "nominal",
          "scale": {
            "domain": [
              "today (this run)",
              "normal (90-day avg)"
            ],
            "range": [
              [
                1
              ],
              [
                8,
                4
              ]
            ]
          },
          "legend": null
        }
      }
    }
  ]
}
